BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=public,extensions;
SELECT no_plan();
INSERT INTO auth.users(id,email,raw_user_meta_data) VALUES
('a1000000-0000-0000-0000-000000000001','change-owner@example.invalid','{"role":"owner"}'),
('a1000000-0000-0000-0000-000000000002','change-tenant@example.invalid','{"role":"tenant"}'),
('a1000000-0000-0000-0000-000000000003','change-stranger@example.invalid','{"role":"owner"}'),
('a1000000-0000-0000-0000-000000000004','change-admin@example.invalid','{"role":"owner"}');
UPDATE public.user_roles SET role='admin' WHERE user_id='a1000000-0000-0000-0000-000000000004';
INSERT INTO public.properties(id,owner_id,name,address) VALUES('a2000000-0000-0000-0000-000000000001','a1000000-0000-0000-0000-000000000001','Change apartment','Address');
INSERT INTO public.tenants(id,owner_id,user_id,name,email) VALUES('a3000000-0000-0000-0000-000000000001','a1000000-0000-0000-0000-000000000001','a1000000-0000-0000-0000-000000000002','Change Tenant','change-tenant@example.invalid');
INSERT INTO public.lease_agreements(id,owner_id,property_id,tenant_id,start_date,end_date,monthly_payment,status,signed_document_file)
VALUES('a4000000-0000-0000-0000-000000000001','a1000000-0000-0000-0000-000000000001','a2000000-0000-0000-0000-000000000001','a3000000-0000-0000-0000-000000000001',date_trunc('month',CURRENT_DATE)::date-interval '1 month',(date_trunc('month',CURRENT_DATE)+interval '3 months - 1 day')::date,60000,'active','signed.pdf');
CREATE FUNCTION pg_temp.change_payload() RETURNS jsonb LANGUAGE sql AS $$SELECT jsonb_build_object('effective_from',(date_trunc('month',CURRENT_DATE)+interval '1 month')::date,'monthly_payment',65000.25,'end_date',(date_trunc('month',CURRENT_DATE)+interval '6 months - 1 day')::date,'note','Renewal and new rent')$$;
SELECT set_config('request.jwt.claims','{"sub":"a1000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
SET LOCAL ROLE authenticated;
SELECT ok(NOT has_table_privilege('authenticated','public.lease_amendments','INSERT,UPDATE,DELETE'),'terms only change through checked RPC');
SELECT ok(NOT has_table_privilege('authenticated','public.lease_amendment_events','INSERT,UPDATE,DELETE'),'clients cannot rewrite audit');
SELECT ok((SELECT bool_and(relrowsecurity) FROM pg_class WHERE oid IN ('public.lease_amendments'::regclass,'public.lease_amendment_events'::regclass)),'RLS enabled');
SELECT throws_ok($$SELECT public.save_lease_amendment('a4000000-0000-0000-0000-000000000001',pg_temp.change_payload()||jsonb_build_object('effective_from',CURRENT_DATE))$$,'23514','Выберите первое число будущего месяца и срок не короче текущего, в пределах пяти лет','retroactive and partial month changes rejected');
SELECT throws_ok($$SELECT public.save_lease_amendment('a4000000-0000-0000-0000-000000000001',pg_temp.change_payload()||'{"monthly_payment":"Infinity"}')$$,'23514','Укажите ставку с точностью до копеек','non-finite rates rejected');
SELECT lives_ok($$SELECT public.save_lease_amendment('a4000000-0000-0000-0000-000000000001',pg_temp.change_payload())$$,'owner drafts new conditions');
SELECT set_config('test.change_id',(SELECT id::text FROM public.lease_amendments),true);
SELECT throws_ok($$SELECT public.save_lease_amendment('a4000000-0000-0000-0000-000000000001',pg_temp.change_payload())$$,'23514','Сначала завершите или отмените текущее предложение','only one open proposal');
SELECT throws_ok($$SELECT public.act_on_lease_amendment(current_setting('test.change_id')::uuid,'accept',1,NULL)$$,'42501','Это действие доступно другой стороне договора','owner cannot accept for tenant');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"a1000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
SET LOCAL ROLE authenticated;
SELECT is((SELECT count(*) FROM public.lease_amendments),0::bigint,'tenant cannot see draft');
SELECT is((SELECT count(*) FROM public.lease_amendment_events),0::bigint,'draft history private');
SELECT throws_ok($$SELECT public.save_lease_amendment('a4000000-0000-0000-0000-000000000001',pg_temp.change_payload())$$,'42501','Нет доступа к изменению договора','tenant cannot create owner proposals');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"a1000000-0000-0000-0000-000000000004","role":"authenticated"}',true);
SET LOCAL ROLE authenticated;
SELECT is((SELECT count(*) FROM public.lease_amendments),1::bigint,'admin sees owner draft');
SELECT lives_ok($$SELECT public.save_lease_amendment('a4000000-0000-0000-0000-000000000001',pg_temp.change_payload(),current_setting('test.change_id')::uuid,1)$$,'admin edits same draft');
SELECT throws_ok($$SELECT public.act_on_lease_amendment(current_setting('test.change_id')::uuid,'submit',1,NULL)$$,'40001','Предложение изменилось. Обновите данные','stale submit rejected');
SELECT lives_ok($$SELECT public.act_on_lease_amendment(current_setting('test.change_id')::uuid,'submit',2,NULL)$$,'admin submits');
SELECT throws_ok($$SELECT public.act_on_lease_amendment(current_setting('test.change_id')::uuid,'accept',3,NULL)$$,'42501','Это действие доступно другой стороне договора','admin cannot approve for tenant');
SELECT throws_ok($$UPDATE public.lease_agreements SET monthly_payment=1 WHERE id='a4000000-0000-0000-0000-000000000001'$$,'23514','Условия закреплены дополнительным соглашением. Создайте новое изменение условий','direct edits blocked while pending');
SELECT throws_ok($$UPDATE public.lease_agreements SET status='completed' WHERE id='a4000000-0000-0000-0000-000000000001'$$,'23514','Сначала завершите или отмените предложение об изменении условий','pending terms settled before checkout');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"a1000000-0000-0000-0000-000000000003","role":"authenticated","user_metadata":{"role":"admin"}}',true);
SET LOCAL ROLE authenticated;
SELECT is((SELECT count(*) FROM public.lease_amendments),0::bigint,'stranger with forged metadata sees nothing');
SELECT throws_ok($$SELECT public.act_on_lease_amendment(current_setting('test.change_id')::uuid,'accept',3,NULL)$$,'42501','Нет доступа к предложению','guessed IDs not actionable');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"a1000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
SET LOCAL ROLE authenticated;
SELECT is((SELECT count(*) FROM public.lease_amendment_events),1::bigint,'tenant sees submitted version only');
SELECT throws_ok($$SELECT public.act_on_lease_amendment(current_setting('test.change_id')::uuid,'reject',3,' ')$$,'23514','Укажите причину отказа','rejection needs reason');
SELECT lives_ok($$SELECT public.act_on_lease_amendment(current_setting('test.change_id')::uuid,'reject',3,'Please reconsider rate')$$,'tenant rejects proposal');
SELECT is((SELECT amount FROM public.rent_charges WHERE period_start=(date_trunc('month',CURRENT_DATE)+interval '1 month')::date),60000::numeric,'rejection does not reprice');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"a1000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
SET LOCAL ROLE authenticated;
SELECT lives_ok($$SELECT public.save_lease_amendment('a4000000-0000-0000-0000-000000000001',pg_temp.change_payload())$$,'owner makes new version after rejection');
SELECT set_config('test.accept_id',(SELECT id::text FROM public.lease_amendments WHERE status='draft'),true);
SELECT lives_ok($$SELECT public.act_on_lease_amendment(current_setting('test.accept_id')::uuid,'submit',1,NULL)$$,'owner submits revised proposal');
INSERT INTO public.rent_payments(charge_id,owner_id,tenant_id,amount,paid_at,payment_method)
SELECT id,owner_id,tenant_id,1000,now(),'cash' FROM public.rent_charges WHERE period_start=(date_trunc('month',CURRENT_DATE)+interval '1 month')::date;
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"a1000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.act_on_lease_amendment(current_setting('test.accept_id')::uuid,'accept',2,NULL)$$,'23514','За затронутые месяцы уже есть оплата или сообщение о ней. Сначала проверьте платежи','partial prepayment blocks silent repricing');
SELECT is((SELECT status FROM public.lease_amendments WHERE id=current_setting('test.accept_id')::uuid),'pending','failed acceptance is atomic');
RESET ROLE;
-- Remove only the fixture prepayment to exercise the independent approval branch.
DELETE FROM public.rent_payments WHERE amount=1000;
SELECT set_config('request.jwt.claims','{"sub":"a1000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
SET LOCAL ROLE authenticated;
INSERT INTO public.payment_reports(charge_id,owner_id,tenant_id,amount,paid_at,payment_method)
SELECT id,owner_id,tenant_id,10,now(),'cash' FROM public.rent_charges WHERE period_start=(date_trunc('month',CURRENT_DATE)+interval '1 month')::date;
SELECT throws_ok($$SELECT public.act_on_lease_amendment(current_setting('test.accept_id')::uuid,'accept',2,NULL)$$,'23514','За затронутые месяцы уже есть оплата или сообщение о ней. Сначала проверьте платежи','pending payment report blocks repricing');
RESET ROLE;
DELETE FROM public.payment_reports;
SELECT set_config('request.jwt.claims','{"sub":"a1000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
SET LOCAL ROLE authenticated;
SELECT lives_ok($$SELECT public.act_on_lease_amendment(current_setting('test.accept_id')::uuid,'accept',2,NULL)$$,'tenant approves future terms and extension');
SELECT lives_ok($$SELECT public.act_on_lease_amendment(current_setting('test.accept_id')::uuid,'accept',2,NULL)$$,'retry does not duplicate acceptance');
SELECT is((SELECT amount FROM public.rent_charges WHERE period_start=date_trunc('month',CURRENT_DATE)::date),60000::numeric,'current rent unchanged');
SELECT is((SELECT amount FROM public.rent_charges WHERE period_start=(date_trunc('month',CURRENT_DATE)-interval '1 month')::date),60000::numeric,'past debt unchanged');
SELECT is((SELECT amount FROM public.rent_charges WHERE period_start=(date_trunc('month',CURRENT_DATE)+interval '1 month')::date),65000.25::numeric,'future rent uses approved rate with kopecks');
SELECT is((SELECT amount FROM public.rent_charges WHERE period_start=(date_trunc('month',CURRENT_DATE)+interval '5 months')::date),65000.25::numeric,'extension generates new months');
SELECT is((SELECT monthly_payment FROM public.lease_agreements WHERE id='a4000000-0000-0000-0000-000000000001'),60000::numeric,'original contract base preserved');
SELECT is((SELECT count(*) FROM public.lease_amendment_events WHERE amendment_id=current_setting('test.accept_id')::uuid AND event_type='accepted'),1::bigint,'only one approval event');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"a1000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
SET LOCAL ROLE authenticated;
SELECT throws_ok($$UPDATE public.lease_agreements SET monthly_payment=1 WHERE id='a4000000-0000-0000-0000-000000000001'$$,'23514','Условия закреплены дополнительным соглашением. Создайте новое изменение условий','accepted schedule cannot be bypassed by raw edit');
SELECT throws_ok($$SELECT public.save_lease_amendment('a4000000-0000-0000-0000-000000000001',pg_temp.change_payload())$$,'23514','Дата должна быть позже последнего согласованного изменения','cannot rewrite an accepted effective month');
SELECT lives_ok($$SELECT public.save_lease_amendment('a4000000-0000-0000-0000-000000000001',pg_temp.change_payload()||jsonb_build_object('effective_from',(date_trunc('month',CURRENT_DATE)+interval '2 months')::date,'monthly_payment',64000))$$,'subsequent rate change can follow accepted schedule');
SELECT set_config('test.second_id',(SELECT id::text FROM public.lease_amendments WHERE status='draft'),true);
SELECT lives_ok($$SELECT public.act_on_lease_amendment(current_setting('test.second_id')::uuid,'submit',1,NULL)$$,'subsequent proposal submitted');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"a1000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
SET LOCAL ROLE authenticated;
SELECT lives_ok($$SELECT public.act_on_lease_amendment(current_setting('test.second_id')::uuid,'accept',2,NULL)$$,'tenant approves second future rate');
SELECT is((SELECT amount FROM public.rent_charges WHERE period_start=(date_trunc('month',CURRENT_DATE)+interval '1 month')::date),65000.25::numeric,'earlier scheduled rate remains');
SELECT is((SELECT amount FROM public.rent_charges WHERE period_start=(date_trunc('month',CURRENT_DATE)+interval '2 months')::date),64000::numeric,'later rate starts in its own month');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"a1000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
SET LOCAL ROLE authenticated;
INSERT INTO public.rent_payments(charge_id,owner_id,tenant_id,amount,paid_at,payment_method)
SELECT id,owner_id,tenant_id,1000,now(),'cash' FROM public.rent_charges WHERE period_start=(date_trunc('month',CURRENT_DATE)+interval '3 months')::date;
SELECT lives_ok($$SELECT public.save_lease_amendment('a4000000-0000-0000-0000-000000000001',pg_temp.change_payload()||jsonb_build_object('effective_from',(date_trunc('month',CURRENT_DATE)+interval '3 months')::date,'monthly_payment',64000,'end_date',(date_trunc('month',CURRENT_DATE)+interval '8 months - 1 day')::date))$$,'extension at same rate can retain prepayment');
SELECT set_config('test.extension_id',(SELECT id::text FROM public.lease_amendments WHERE status='draft'),true);
SELECT lives_ok($$SELECT public.act_on_lease_amendment(current_setting('test.extension_id')::uuid,'submit',1,NULL)$$,'submit extension-only proposal');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"a1000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
SET LOCAL ROLE authenticated;
SELECT lives_ok($$SELECT public.act_on_lease_amendment(current_setting('test.extension_id')::uuid,'accept',2,NULL)$$,'tenant agrees extension without repricing paid period');
SELECT is((SELECT paid_amount FROM public.rent_charges WHERE period_start=(date_trunc('month',CURRENT_DATE)+interval '3 months')::date),1000::numeric,'prepayment survives extension');
SELECT is((SELECT amount FROM public.rent_charges WHERE period_start=(date_trunc('month',CURRENT_DATE)+interval '3 months')::date),64000::numeric,'prepaid month retains original agreed base');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"a1000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
SET LOCAL ROLE authenticated;
SELECT lives_ok($$UPDATE public.lease_agreements SET status='completed' WHERE id='a4000000-0000-0000-0000-000000000001'$$,'agreement can end after amendments are settled');
SELECT is((SELECT count(*) FROM public.rent_charges WHERE paid_amount=1000),1::bigint,'checkout preserves advance payment even after term changes');
RESET ROLE;
SELECT set_config('request.jwt.claims','{}',true);
SET LOCAL ROLE anon;
SELECT throws_ok($$SELECT * FROM public.lease_amendments$$,'42501','permission denied for table lease_amendments','anonymous denied');
SELECT throws_ok($$SELECT public.act_on_lease_amendment(current_setting('test.accept_id')::uuid,'accept',2,NULL)$$,'42501','permission denied for function act_on_lease_amendment','anonymous RPC denied');
RESET ROLE;
SELECT * FROM finish();ROLLBACK;
